// One item per due run (from Query Due Runs). Decide what happens to it:
// stop_replied | complete | send.
const r = $json;
const steps = r.steps || [];

if (r.contact_replied) {
  return [{ json: { action: 'stop_replied', run_id: r.run_id } }];
}

const step = steps[r.current_step_index];
if (!step) {
  return [{ json: { action: 'complete', run_id: r.run_id } }];
}

const isFinal = r.current_step_index === steps.length - 1;
const nextStep = isFinal ? null : steps[r.current_step_index + 1];

const contactName = r.contact_name || 'there';
const subject = (step.subject || '').replace(/\{\{\s*contact_name\s*\}\}/g, contactName);
const body = (step.body || '').replace(/\{\{\s*contact_name\s*\}\}/g, contactName);

const mode = r.autonomy_rules?.send_follow_up?.mode === 'autonomous' ? 'autonomous' : 'approval_required';

return [{
  json: {
    action: 'send',
    run_id: r.run_id,
    tenant_id: r.tenant_id,
    contact_id: r.contact_id,
    contact_email: r.contact_email,
    from_email: r.connected_gmail_address || null,
    subject,
    body,
    mode,
    draft_status: mode === 'autonomous' ? 'auto_sent' : 'pending',
    is_final: isFinal,
    next_step_day_offset: nextStep ? (nextStep.day_offset ?? 0) : null,
  }
}];

parameters.query:
update follow_up_runs
set status = 'stopped', stop_reason = 'contact_replied', next_run_at = null, updated_at = now()
where id = $1;

update follow_up_runs
set status = 'completed', next_run_at = null, updated_at = now()
where id = $1;

insert into email_drafts (tenant_id, contact_id, to_email, from_email, subject, body, category, status, follow_up_run_id)
values ($1, $2, $3, $4, $5, $6, 'follow_up', $7, $8)
returning *;

