// Same raw RFC 2822 base64url pattern as 15/18.
const d = $json;
const raw =
  `To: ${d.to_email}\r\n` +
  `Subject: ${d.subject}\r\n` +
  `Content-Type: text/plain; charset=UTF-8\r\n\r\n` +
  `${d.body}`;
const encoded = Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { ...d, raw_message: encoded } }];

// Passes through so Advance Run can read $('Determine Action').item.json for
// run_id/is_final/next_step_day_offset regardless of which branch
// (Autonomous? true or false) fed into it -- needed because a Gmail send
// failure (continueOnFail) would otherwise still reach here with whatever
// $json the failed HTTP node produced, not the original Determine Action data.
return [{ json: $json }];
